52	/**
53	 * Workspaces in the main process (ADR 0032): the registry, the gate every item-scoped call
54	 * runs through, and the switch transaction with its IPC. `initWorkspaces()` runs once in
55	 * `app.whenReady`, before any window exists, so the preload can read the stamp at load.
56	 */
57	
58	/** How long a window may take to prepare (an unsaved editor waits on the user's answer). */
59	const PREPARE_TIMEOUT_MS = 120_000;
60	
61	let registry: WorkspaceRegistry | null = null;
62	/** Which provider syncs each workspace's folder (spec, Synced folders). */
63	const syncStates = new SyncStates();
64	/**
65	 * Synced workspaces whose last availability check did not answer in time: available under
66	 * their registered id (an evicted `identity.json` is downloading), but not a move target.
67	 */
68	const unverified = new Set<string>();
69	let gate: WorkspaceGate | null = null;
70	let workspaceSettings: WorkspaceSettings | null = null;
71	
72	export interface WorkspaceHost {
73	  /** What is writing into the active workspace (the switch lock). A move is added here. */
74	  busy(): "recording" | "exporting" | null;
75	  /** Dismiss the capture toast and drop the retained quiet-capture bytes. */
76	  dropPendingCaptures(): void;
77	  /** Re-list every window's library (`library:changed`). */
78	  broadcastLibraryChanged(): void;
79	  /**
80	   * A move committed: its cloud asset now belongs to `targetId`. Best effort, never awaited
81	   * by the move (ADR 0033, the cloud step); the library's assignment queue retries it.
82	   */
83	  itemMoved?(assetId: string, targetId: string): void;
84	}
85	
86	let host: WorkspaceHost | null = null;
87	
88	/** The group move running now, if any: it holds the switch lock from its first item to its last. */
89	let moveRun: { stop: boolean } | null = null;
90	
91	/** What locks the switcher right now. */
92	function busyNow(): WorkspaceBusy | null {
93	  return host?.busy() ?? (moveRun ? "moving" : null);
94	}
95	
96	function requireRegistry(): WorkspaceRegistry {
97	  if (!registry) throw new Error("workspaces: not initialized");
98	  return registry;
99	}
100	
101	export function workspaceGate(): WorkspaceGate {
102	  if (!gate) throw new Error("workspaces: not initialized");
103	  return gate;
104	}
105	
106	export async function initWorkspaces(): Promise<void> {
107	  registry = await WorkspaceRegistry.open({
108	    preferencesFile: join(app.getPath("userData"), "preferences.json"),
109	    defaultDirectory: defaultVaultDirectory(),
110	    newId: () => uuidv7(),
111	    onPreferencesWritten: forgetCachedPreferences,
112	  });
113	  gate = new WorkspaceGate(registry.active().id);
114	  // Re-detected on every launch (a folder may have been moved into Drive since).
115	  await Promise.all(registry.entries().map((entry) => syncStates.refresh(entry)));
116	  await initWorkspaceSettings(registry);
117	  // The preload reads the stamp once, synchronously, before the page's scripts run, so it
118	  // is answered from here, before any window can exist.
119	  ipcMain.on(IPC_CHANNELS.workspacesStampSync, (event) => {
120	    event.returnValue = workspaceGate().stamp satisfies WorkspaceStamp;
121	  });
122	  if (registry.readOnly) {
123	    console.warn("[workspaces] preferences.json does not parse: running read-only until restart");
124	  }
125	  // A move the app died in is finished before anything lists either workspace.
126	  await healPendingMoves();
127	}
128	
129	/**
130	 * Per-workspace setting overrides (ADR 0034): the module that owns the two override files, wired
131	 * to the registry and to the settings store, which resolves the effective settings from it.
132	 * The active workspace's folder file is read once here, at app start.
133	 */
134	async function initWorkspaceSettings(reg: WorkspaceRegistry): Promise<void> {
135	  const machine = await MachineSettingsStore.open(
136	    join(app.getPath("userData"), "workspace-settings.json"),
137	  );
138	  const settings = new WorkspaceSettings({
139	    machine,
140	    workspaces: () => reg.entries().map(({ id, name, path }) => ({ id, name, path })),
141	    activeId: () => reg.active().id,
142	    isAvailable: async (id) => (await availabilityOf(id)).availability.state === "available",
143	    getAll: getAllLevelSettings,
144	    writeAll: (patch) => {
145	      updateAppSettings(patch);
146	    },
147	    effective: getAppSettings,
148	    changed: notifyOverridesChanged,
149	    now: () => Date.now(),
150	  });
151	  workspaceSettings = settings;
152	  setOverridesSource(() => settings.activeOverrides());
153	  await settings.refresh(reg.active().id);
154	}
155	
156	function requireWorkspaceSettings(): WorkspaceSettings {
157	  if (!workspaceSettings) throw new Error("workspaces: settings not initialized");
158	  return workspaceSettings;
159	}
160	
161	/**
162	 * Read the active workspace's folder overrides again. A capture calls this as it starts, so a
163	 * file a sync changed since the last read is inactive for this capture and not applied unasked
164	 * (ADR 0034, decision 8). A read that fails leaves the overrides inactive.
165	 */
166	export async function refreshActiveWorkspaceSettings(): Promise<void> {
167	  await workspaceSettings?.refresh(requireRegistry().active().id);
168	}
169	
170	/**
171	 * The availability check, bounded for a synced workspace: a provider that does not answer
172	 * must never hang the switcher, a capture or a move, and the check never lists the provider's
173	 * root (spec, Availability and Synced folders). Unanswered, a folder that `stat` still sees is
174	 * available under its registered id, unverified; one that `stat` cannot see is missing.
175	 */
176	async function availabilityOf(id: string): Promise<{ availability: Availability; id: string }> {
177	  const reg = requireRegistry();
178	  const entry = reg.get(id);
179	  if (!entry || syncStates.of(entry) === null) return reg.availability(id);
180	  const answered = await boundedProbe(reg.availability(id), null);
181	  if (answered) {
182	    unverified.delete(id);
183	    return answered;
184	  }
185	  const seen = await boundedProbe(
186	    stat(entry.path).then((info) => info.isDirectory()),
187	    false,
188	    1_000,
189	  );
190	  if (!seen) return { availability: { state: "unavailable", reason: "missing" }, id };
191	  unverified.add(id);
192	  return { availability: { state: "available" }, id };
193	}
194	
195	function movesJournalDir(): string {
196	  return join(app.getPath("userData"), "workspace-moves");
197	}
198	
199	/** The folder a workspace of a move lives in now, or null while it is not connected. */
200	async function resolveMoveSide(side: MoveSide): Promise<string | null> {
201	  const reg = requireRegistry();
202	  if (!reg.get(side.workspaceId)) return null;
203	  const { availability, id } = await availabilityOf(side.workspaceId);
204	  if (availability.state !== "available") return null;
205	  // An identity still downloading cannot prove the folder is this workspace: no move yet.
206	  if (unverified.has(id)) return null;
207	  return reg.get(id)?.path ?? null;
208	}
209	
210	/** A workspace as one side of a move: a synced one stages in its scratch folder (decision 15). */
211	function moveSideOf(entry: WorkspaceEntry, directory = entry.path): MoveSide {
212	  return syncStates.of(entry) === null
213	    ? { workspaceId: entry.id, directory }
214	    : { workspaceId: entry.id, directory, scratch: scratchRoot(app.getPath("userData"), entry.id) };
215	}
216	
217	/**
218	 * Finish every move the app died in (ADR 0033, decision 6). At startup and before each group.
219	 * An entry whose workspace is not connected waits for a later run.
220	 */
221	async function healPendingMoves(): Promise<void> {
222	  try {
223	    const report = await healMoves({ journalDir: movesJournalDir(), resolve: resolveMoveSide });
224	    if (report.healed > 0) host?.broadcastLibraryChanged();
225	    if (report.quarantined.length > 0) {
226	      console.error(
227	        `[workspaces] ${report.quarantined.length} interrupted move(s) need a look; journal kept in`,
228	        movesJournalDir(),
229	      );
230	    }
231	  } catch (error) {
232	    console.error("[workspaces] healing interrupted moves failed", error);
233	  }
234	}
235	
236	let deviceId: Promise<string> | null = null;
237	
238	/**
239	 * `workspaces:move-items`: a group of single moves from the active workspace to `targetId`,
240	 * one after another (ADR 0033, decision 14). Runs inside the workspace gate, so the window's
241	 * stamp must still be current, and holds the switch lock from the first item to the last.
242	 */
243	async function moveItems(
244	  sender: Electron.WebContents,
245	  stamp: unknown,
246	  input: unknown,
247	): Promise<MoveItemsResult> {
248	  const reg = requireRegistry();
249	  const { items: rawItems, targetId } = (input ?? {}) as { items?: unknown; targetId?: unknown };
250	  const items: MoveItemRef[] = Array.isArray(rawItems)
251	    ? rawItems.filter(
252	        (item): item is MoveItemRef =>
253	          !!item &&
254	          typeof (item as MoveItemRef).id === "string" &&
255	          typeof (item as MoveItemRef).assetId === "string",
256	      )
257	    : [];
258	  const target = typeof targetId === "string" ? targetId : "";
259	  const refuseAll = (reason: MoveItemsResult["failed"][number]["reason"]): MoveItemsResult => ({
260	    targetId: target,
261	    moved: [],
262	    failed: items.map((item) => ({ id: item.id, reason })),
263	    skipped: [],
264	  });
265	  if (moveRun) return refuseAll("busy");
266	  if (!workspaceGate().isCurrent(stamp)) return refuseAll("stale");
267	  if (vaultActivity.inMaintenance) return refuseAll("maintenance");
268	
269	  const run = { stop: false };
270	  moveRun = run;
271	  void broadcastState();
272	  try {
273	    return await workspaceGate().run(stamp, () =>
274	      vaultActivity.run("library", async () => {
275	        await healPendingMoves();
276	        const source = reg.active();
277	        // A rejected read is not kept: the next group asks again.
278	        deviceId ??= loadDeviceId(app.getPath("userData")).catch((error: unknown) => {
279	          deviceId = null;
280	          throw error;
281	        });
282	        const device = await deviceId;
283	        const result = await runMoveGroup(
284	          items,
285	          async (item) => {
286	            // Checked per item, when its turn comes (decision 14).
287	            if (host?.busy()) return { ok: false, reason: "busy" };
288	            if (target === source.id) return { ok: false, reason: "same-workspace" };
289	            const entry = reg.get(target);
290	            if (!entry) return { ok: false, reason: "target-unavailable" };
291	            const directory = await resolveMoveSide({ workspaceId: target, directory: "" });
292	            if (directory === null) return { ok: false, reason: "target-unavailable" };
293	            const outcome = await moveItem(
294	              {
295	                source: moveSideOf(source),
296	                target: moveSideOf(entry, directory),
297	                id: item.id,
298	                expectedAssetId: item.assetId,
299	              },
300	              { journalDir: movesJournalDir(), deviceId: () => device, dragLedger },
301	            );
302	            if (!outcome.ok) return { ok: false, reason: outcome.reason };
303	            // The local move is committed; the cloud follows, best effort, never blocking it.
304	            try {
305	              host?.itemMoved?.(item.assetId, target);
306	            } catch (error) {
307	              console.error("[workspaces] could not queue the cloud assignment", error);
308	            }
309	            return { ok: true, newId: outcome.newId };
310	          },
311	          {
312	            targetId: target,
313	            stopped: () => run.stop,
314	            onProgress: (progress) => {
315	              if (!sender.isDestroyed()) {
316	                sender.send(IPC_CHANNELS.workspacesMoveProgress, progress);
317	              }
318	            },
319	          },
320	        );
321	        return result;
322	      }),
323	    );
324	  } catch (error) {
325	    console.error("[workspaces] group move refused", error);
326	    return refuseAll(refusalOfError(error));
327	  } finally {
328	    moveRun = null;
329	    host?.broadcastLibraryChanged();
330	    void broadcastState();
331	  }
332	}
333	
334	export function activeWorkspace(): WorkspaceEntry {
335	  return requireRegistry().active();
336	}
337	
338	/**
339	 * What the cloud filter needs from the registry (`workspace-filter.ts`, decisions 3, 4, 23);
340	 * the caller adds the pending assignments.
341	 */
342	export function cloudScopeBase(): Omit<CloudScope, "pending"> {
343	  const reg = requireRegistry();
344	  return {
345	    activeId: reg.active().id,
346	    legacyOwnerId: reg.state.legacyCloudOwnerId,
347	    registered: new Set(reg.entries().map((entry) => entry.id)),
348	    unassignedHidden: reg.state.cloudAssignedAt !== undefined,
349	  };
350	}
351	
352	/** The first "Assign to workspace…": the unassigned stop showing in the legacy owner. */
353	export async function markCloudAssigned(): Promise<void> {
354	  await requireRegistry().markCloudAssigned();
355	}
356	
357	/** Every registered workspace, by id, for the cloud page. */
358	export function registeredWorkspaces(): readonly WorkspaceEntry[] {
359	  return requireRegistry().entries();
360	}
361	
362	/** The provider that syncs a workspace's folder, or null. */
363	export function workspaceSync(entry: WorkspaceEntry): SyncProvider | null {
364	  return syncStates.of(entry);
365	}
366	
367	/** The active workspace's eviction probe, when it is synced (`LibraryVault`, the media protocol). */
368	export function activeEvictionProbe(): EvictionProbe | null {
369	  return syncStates.of(requireRegistry().active()) === null ? null : probeDataless;
370	}
371	
372	/** The scratch folder of the active workspace when it is synced, else null. */
373	export function activeScratch(): string | null {
374	  const active = requireRegistry().active();
375	  return syncStates.of(active) === null ? null : scratchRoot(app.getPath("userData"), active.id);
376	}
377	
378	/**
379	 * The scratch staging folder of the workspace registered at `vaultDir`, synced or not (the
380	 * stranded-take sweep reads it whenever it exists), or null for a folder no workspace holds.
381	 */
382	export function scratchStagingFor(vaultDir: string): string | null {
383	  const entry = requireRegistry()
384	    .entries()
385	    .find((candidate) => candidate.path === vaultDir);
386	  return entry ? scratchTmp(app.getPath("userData"), entry.id) : null;
387	}
388	
389	/**
390	 * Recording staging for a folder (`RecordingWriter.stagingFor`): the scratch folder of the
391	 * synced workspace that lives there, or null to stage in `.kaipu/tmp/`.
392	 */
393	export function syncedStagingFor(vaultDir: string): string | null {
394	  const entry = requireRegistry()
395	    .entries()
396	    .find((candidate) => candidate.path === vaultDir);
397	  if (!entry || syncStates.of(entry) === null) return null;
398	  return scratchTmp(app.getPath("userData"), entry.id);
399	}
400	
401	/** The workspace's name for a label, only once a second one exists (window title, tray). */
402	function prefixName(): string | null {
403	  const reg = requireRegistry();
404	  return reg.entries().length > 1 ? reg.active().name : null;
405	}
406	
407	/** The capture target was unplugged or replaced: refuse, never save anywhere else. */
408	export class WorkspaceNotConnectedError extends Error {
409	  constructor(readonly workspaceName: string) {
410	    const t = createMainTranslator(getAppSettings().locale);
411	    super(t("workspaces.notConnectedError", { name: workspaceName }));
412	    this.name = "WorkspaceNotConnectedError";
413	  }
414	}
415	
416	/**
417	 * The active workspace, checked to be connected, for a capture that is about to start.
418	 * Throws `WorkspaceNotConnectedError` otherwise; a switch in progress counts as stale.
419	 */
420	export async function requireCaptureWorkspace(): Promise<WorkspaceEntry> {
421	  const reg = requireRegistry();
422	  if (workspaceGate().switching) throw new StaleWorkspaceError();
423	  const active = reg.active();
424	  const { availability, id } = await availabilityOf(active.id);
425	  if (workspaceGate().adopt(active.id, id, reg.active().id)) void broadcastState();
426	  if (availability.state !== "available") throw new WorkspaceNotConnectedError(active.name);
427	  await refreshActiveWorkspaceSettings();
428	  return reg.active();
429	}
430	
431	/** Every workspace whose folder is reachable, for the startup and quit sweeps. */
432	export async function availableWorkspacePaths(): Promise<string[]> {
433	  const reg = requireRegistry();
434	  const paths: string[] = [];
435	  // A copy: a probe may update an entry (a pending one adopting its folder's id).
436	  for (const entry of reg.entries().slice()) {
437	    const { availability } = await availabilityOf(entry.id);
438	    if (availability.state === "available") paths.push(entry.path);
439	  }
440	  return paths;
441	}
442	
443	async function listState(): Promise<WorkspacesState> {
444	  const reg = requireRegistry();
445	  const views: WorkspaceView[] = [];
446	  for (const entry of reg.entries().slice()) {
447	    const { availability, id } = await availabilityOf(entry.id);
448	    // A pending active entry that adopted its folder's id: windows must take the new stamp.
449	    if (workspaceGate().adopt(entry.id, id, reg.active().id)) void broadcastState();
450	    // A synced folder's count is bounded too: `readdir` never downloads, but a stuck
451	    // provider must not hang the switcher.
452	    const count =
453	      availability.state === "available"
454	        ? await boundedProbe(
455	            new LibraryVault(entry.path).countMedia().catch(() => null),
456	            null,
457	          )
458	        : null;
459	    // Which volume the folder is on: "Move to" says whether a move copies or is instant.
460	    const device =
461	      availability.state === "available"
462	        ? await stat(entry.path).then(
463	            (info) => String(info.dev),
464	            () => null,
465	          )
466	        : null;
467	    const current = reg.get(id) ?? entry;
468	    views.push(toWorkspaceView(current, availability, count, device, syncStates.of(current)));
469	  }
470	  const { activeId, hintDismissedAt } = reg.state;
471	  return {
472	    activeId,
473	    generation: workspaceGate().stamp.generation,
474	    hintDismissed: hintDismissedAt !== undefined,
475	    busy: busyNow(),
476	    readOnly: reg.readOnly,
477	    workspaces: views,
478	  };
479	}
480	
481	function sendToAll(channel: string, payload?: unknown): void {
482	  for (const window of BrowserWindow.getAllWindows()) {
483	    if (!window.isDestroyed()) window.webContents.send(channel, payload);
484	  }
485	}
486	
487	async function broadcastState(): Promise<void> {
488	  sendToAll(IPC_CHANNELS.workspacesChanged, await listState());
489	}
490	
491	/** The main window's title follows the active workspace and the page's own title. */
492	export function attachWindowTitle(window: BrowserWindow): void {
493	  let pageTitle = APP_TITLE;
494	  const apply = (): void => {
495	    if (!window.isDestroyed()) window.setTitle(composeWindowTitle(pageTitle, prefixName()));
496	  };
497	  window.on("page-title-updated", (event, title) => {
498	    event.preventDefault();
499	    pageTitle = title;
500	    apply();
501	  });
502	  titleAppliers.add(apply);
503	  window.on("closed", () => titleAppliers.delete(apply));
504	  apply();
505	}
506	
507	const titleAppliers = new Set<() => void>();
508	
509	function refreshTitles(): void {
510	  for (const apply of titleAppliers) apply();
511	}
512	
513	const prepareRequests = new PrepareRequests(IPC_CHANNELS.workspacesPrepare, PREPARE_TIMEOUT_MS);
514	
515	/** What every change to the active workspace shares: the lock, the windows, the commit. */
516	function activeTransactionDeps(): ActiveTransactionDeps {
517	  return {
518	    gate: workspaceGate(),
519	    // The group move holds this lock too: a folder cannot change under it.
520	    busy: busyNow,
521	    prepareWindows: () => prepareRequests.prepare(BrowserWindow.getAllWindows()),
522	    abortWindows: () => sendToAll(IPC_CHANNELS.workspacesPrepareAbort),
523	    dropPendingCaptures: () => host?.dropPendingCaptures(),
524	    afterCommit: () => {
525	      // The new workspace's effective settings reach every window and every main listener.
526	      notifyOverridesChanged();
527	      refreshTitles();
528	      void broadcastState();
529	      host?.broadcastLibraryChanged();
530	    },
531	  };
532	}
533	
534	async function runSwitch(id: string): Promise<WorkspaceSwitchResult> {
535	  const reg = requireRegistry();
536	  const result = await switchWorkspace(
537	    {
538	      ...activeTransactionDeps(),
539	      activeId: () => reg.active().id,
540	      isKnown: (candidate) => reg.get(candidate) !== undefined,
541	      readOnly: () => reg.readOnly,
542	      availability: (candidate) => availabilityOf(candidate),
543	      persistActive: async (target) => {
544	        await reg.setActive(target);
545	        // The target's overrides are read before the switch is certain, so the effective
546	        // settings are ready the moment it commits. A read that fails leaves them inactive.
547	        await workspaceSettings?.refresh(target);
548	      },
549	    },
550	    id,
551	  );
552	  // A refused switch still re-lists, so a LOCKED or NOT CONNECTED menu shows why.
553	  if (!result.ok) void broadcastState();
554	  return result;
555	}
556	
557	/** Folder picker for Add workspace; initializes or adopts the folder, then switches to it. */
558	async function addWorkspace(
559	  sender: Electron.WebContents,
560	  request: { activate?: unknown } = {},
561	): Promise<WorkspaceAddResult> {
562	  const reg = requireRegistry();
563	  if (reg.readOnly) return { ok: false, reason: "read-only" };
564	  const window = BrowserWindow.fromWebContents(sender);
565	  const t = createMainTranslator(getAppSettings().locale);
566	  const options: Electron.OpenDialogOptions = {
567	    title: t("dialogs.addWorkspace"),
568	    buttonLabel: t("dialogs.addWorkspaceButton"),
569	    properties: ["openDirectory", "createDirectory"],
570	  };
571	  const picked = window
572	    ? await dialog.showOpenDialog(window, options)
573	    : await dialog.showOpenDialog(options);
574	  const chosen = picked.filePaths[0];
575	  if (picked.canceled || !chosen) return { ok: false, reason: "cancelled" };
576	
577	  const outcome = await reg.add(chosen);
578	  if (outcome.ok) await syncStates.refresh(outcome.entry);
579	  if (!outcome.ok) {
580	    if (outcome.reason !== "read-only") {
581	      const message = { type: "error" as const, message: t("dialogs.folderUnusable") };
582	      const detail = t(
583	        outcome.reason === "unreadable"
584	          ? "dialogs.workspaceUnreadableDetail"
585	          : "dialogs.folderUnusableDetail",
586	      );
587	      await (window
588	        ? dialog.showMessageBox(window, { ...message, detail })
589	        : dialog.showMessageBox({ ...message, detail }));
590	    }
591	    return { ok: false, reason: outcome.reason === "read-only" ? "read-only" : "not-writable" };
592	  }
593	  // Adding a workspace answers the "New: workspaces" hint too.
594	  await reg.dismissHint();
595	  const { availability } = await availabilityOf(outcome.entry.id);
596	  // An adopted folder may bring its own settings file: read it now, so it shows as pending.
597	  await workspaceSettings?.refresh(outcome.entry.id);
598	  // Then make it the active one, through the same transaction as any other switch. A
599	  // refusal (a recording running) leaves it registered and inactive. "Move to ▸ New
600	  // workspace…" keeps it inactive: the item goes there, the user stays here.
601	  if (request.activate !== false) await runSwitch(outcome.entry.id);
602	  await broadcastState();
603	  return {
604	    ok: true,
605	    workspace: toWorkspaceView(
606	      outcome.entry,
607	      availability,
608	      null,
609	      null,
610	      syncStates.of(outcome.entry),
611	    ),
612	  };
613	}
614	
615	/**
616	 * New workspace: a new folder next to the Default workspace's, only Kaipu's files in it, then
617	 * the same switch as any other. A refused switch (a recording running) leaves it registered.
618	 */
619	async function createWorkspace(input: unknown): Promise<WorkspaceCreateResult> {
620	  const reg = requireRegistry();
621	  const { name, color, activate } = (input ?? {}) as {
622	    name?: unknown;
623	    color?: unknown;
624	    activate?: unknown;
625	  };
626	  if (typeof name !== "string") return { ok: false, reason: "invalid-name" };
627	  if (typeof color !== "string") return { ok: false, reason: "invalid-color" };
628	  const outcome = await reg.create({ name, color });
629	  if (!outcome.ok) return outcome;
630	  await syncStates.refresh(outcome.entry);
631	  await reg.dismissHint();
632	  const { availability } = await availabilityOf(outcome.entry.id);
633	  // "Move to ▸ New workspace…" creates it inactive: the item goes there, the user stays here.
634	  const switchResult: WorkspaceSwitchResult =
635	    activate === false ? { ok: true } : await runSwitch(outcome.entry.id);
636	  await broadcastState();
637	  return {
638	    ok: true,
639	    workspace: toWorkspaceView(
640	      outcome.entry,
641	      availability,
642	      null,
643	      null,
644	      syncStates.of(outcome.entry),
645	    ),
646	    switchResult,
647	  };
648	}
649	
650	async function editWorkspace(input: unknown): Promise<WorkspaceEditResult> {
651	  const reg = requireRegistry();
652	  const { id, name, color } = (input ?? {}) as { id?: unknown; name?: unknown; color?: unknown };
653	  if (typeof id !== "string") return { ok: false, reason: "unknown" };
654	  const outcome = await reg.edit(id, {
655	    ...(typeof name === "string" ? { name } : {}),
656	    ...(typeof color === "string" ? { color } : {}),
657	  });
658	  if (!outcome.ok) return outcome;
659	  const { availability } = await availabilityOf(outcome.entry.id);
660	  // The window title shows the active workspace's name, and the tiles show the initials.
661	  refreshTitles();
662	  await broadcastState();
663	  return {
664	    ok: true,
665	    workspace: toWorkspaceView(
666	      outcome.entry,
667	      availability,
668	      null,
669	      null,
670	      syncStates.of(outcome.entry),
671	    ),
672	    savedToFolder: outcome.savedToFolder,
673	  };
674	}
675	
676	function overridableKeys(value: unknown): OverridableKey[] | null {
677	  if (!Array.isArray(value) || !value.every(isOverridableKey)) return null;
678	  return value;
679	}
680	
681	/** `settings:*` channels for the other levels (ADR 0034). The generic ones stay in settings-store. */
682	function registerSettingsScopeHandlers(): void {
683	  ipcMain.handle(IPC_CHANNELS.settingsGetScoped, (_event, scope: unknown) =>
684	    requireWorkspaceSettings().getScoped(typeof scope === "string" ? scope : "all"),
685	  );
686	  ipcMain.handle(
687	    IPC_CHANNELS.settingsSetOverride,
688	    (_event, workspaceId: unknown, key: unknown, value: unknown) =>
689	      typeof workspaceId === "string" && isOverridableKey(key)
690	        ? requireWorkspaceSettings().setOverride(workspaceId, key, value ?? null)
691	        : { ok: false, reason: "not-overridable" },
692	  );
693	  ipcMain.handle(
694	    IPC_CHANNELS.settingsResetOverrides,
695	    (_event, workspaceId: unknown, keys: unknown) => {
696	      const checked = overridableKeys(keys);
697	      return typeof workspaceId === "string" && checked
698	        ? requireWorkspaceSettings().resetOverrides(workspaceId, checked)
699	        : { ok: false, reason: "not-overridable" };
700	    },
701	  );
702	  ipcMain.handle(IPC_CHANNELS.settingsCopyToAll, (_event, workspaceId: unknown, keys: unknown) => {
703	    const checked = overridableKeys(keys);
704	    return typeof workspaceId === "string" && checked
705	      ? requireWorkspaceSettings().copyToAll(workspaceId, checked)
706	      : { ok: false, reason: "not-overridable" };
707	  });
708	  ipcMain.handle(
709	    IPC_CHANNELS.settingsResolvePending,
710	    (_event, workspaceId: unknown, decision: unknown, sha256: unknown) =>
711	      typeof workspaceId === "string" &&
712	      (decision === "use" || decision === "ignore") &&
713	      typeof sha256 === "string"
714	        ? requireWorkspaceSettings().resolvePending(workspaceId, decision, sha256)
715	        : { ok: false, reason: "nothing-pending" },
716	  );
717	}
718	
719	/**
720	 * "Change folder…": the native folder picker, then the workspace is pointed at that folder.
721	 * Relocating never moves or copies files; the rules are in `relocate.ts` and the registry.
722	 */
723	async function relocateFolder(
724	  sender: Electron.WebContents,
725	  id: unknown,
726	): Promise<WorkspaceRelocateResult> {
727	  const reg = requireRegistry();
728	  const deps = { ...activeTransactionDeps(), registry: reg };
729	  if (typeof id !== "string") return { ok: false, reason: "unknown" };
730	  // Locked or read-only: say so now, instead of after the user picked a folder.
731	  const refused = relocateRefusal(deps, id);
732	  if (refused) return refused;
733	  const entry = reg.get(id);
734	  if (!entry) return { ok: false, reason: "unknown" };
735	
736	  const window = BrowserWindow.fromWebContents(sender);
737	  const t = createMainTranslator(getAppSettings().locale);
738	  const options: Electron.OpenDialogOptions = {
739	    title: t("dialogs.relocateWorkspace", { name: entry.name }),
740	    buttonLabel: t("dialogs.relocateWorkspaceButton"),
741	    // Where it was: a moved folder is usually next to where it used to be.
742	    defaultPath: dirname(entry.path),
743	    properties: ["openDirectory", "createDirectory"],
744	  };
745	  const picked = window
746	    ? await dialog.showOpenDialog(window, options)
747	    : await dialog.showOpenDialog(options);
748	  const chosen = picked.filePaths[0];
749	  if (picked.canceled || !chosen) return { ok: false, reason: "cancelled" };
750	
751	  const outcome = await relocateWorkspace(deps, id, chosen);
752	  if (!outcome.ok) return outcome;
753	  // The new folder may be a synced one (Google Drive): detect it, and probe it bounded.
754	  const current = reg.get(outcome.entry.id) ?? outcome.entry;
755	  await syncStates.refresh(current);
756	  const { availability } = await availabilityOf(current.id);
757	  // The active workspace re-lists inside its transaction; any other one only needs the state.
758	  refreshTitles();
759	  await broadcastState();
760	  return {
761	    ok: true,
762	    workspace: toWorkspaceView(current, availability, null, null, syncStates.of(current)),
763	    ...(outcome.unchanged ? { unchanged: true as const } : {}),
764	  };
765	}
766	
767	export function registerWorkspaceHandlers(deps: WorkspaceHost): void {
768	  host = deps;
769	  registerSettingsScopeHandlers();
770	  ipcMain.handle(IPC_CHANNELS.workspacesList, () => listState());
771	  ipcMain.handle(IPC_CHANNELS.workspacesSwitch, (_event, id: unknown) =>
772	    typeof id === "string" ? runSwitch(id) : { ok: false, reason: "unknown" },
773	  );
774	  ipcMain.handle(IPC_CHANNELS.workspacesAdd, (event, options: unknown) =>
775	    addWorkspace(event.sender, (options ?? {}) as { activate?: unknown }),
776	  );
777	  ipcMain.handle(IPC_CHANNELS.workspacesMoveItems, (event, stamp: unknown, input: unknown) =>
778	    moveItems(event.sender, stamp, input),
779	  );
780	  ipcMain.handle(IPC_CHANNELS.workspacesCancelMove, () => {
781	    if (moveRun) moveRun.stop = true;
782	  });
783	  ipcMain.handle(IPC_CHANNELS.workspacesCreate, (_event, input: unknown) => createWorkspace(input));
784	  ipcMain.handle(IPC_CHANNELS.workspacesEdit, (_event, input: unknown) => editWorkspace(input));
785	  ipcMain.handle(IPC_CHANNELS.workspacesRelocate, (event, id: unknown) =>
786	    relocateFolder(event.sender, id),
787	  );
788	  ipcMain.handle(
789	    IPC_CHANNELS.workspacesCheckLocation,
790	    (_event, name: unknown): Promise<LocationCheck> =>
791	      typeof name === "string"
792	        ? requireRegistry().checkNewLocation(name)
793	        : Promise.resolve({ path: null, state: "parent-missing" }),
794	  );
795	  ipcMain.handle(
796	    IPC_CHANNELS.workspacesRemove,
797	    async (_event, id: unknown): Promise<WorkspaceRemoveResult> => {
798	      if (typeof id !== "string") return { ok: false, reason: "unknown" };
799	      const result = await requireRegistry().remove(id);
800	      if (result.ok) {
801	        refreshTitles();
802	        await broadcastState();
803	      }
804	      return result;
805	    },
806	  );
807	  ipcMain.handle(IPC_CHANNELS.workspacesOpenFolder, async (_event, id: unknown) => {
808	    const entry = typeof id === "string" ? requireRegistry().get(id) : undefined;
809	    if (!entry) return;
810	    // shell.openPath never creates the folder: a missing one reports an error string.
811	    const error = await shell.openPath(entry.path);
812	    if (error) console.error("failed to open the workspace folder", error);
813	  });
814	  ipcMain.handle(IPC_CHANNELS.workspacesDismissHint, async () => {
815	    await requireRegistry().dismissHint();
816	    await broadcastState();
817	  });
818	  ipcMain.on(IPC_CHANNELS.workspacesPrepareResult, (_event, result: WorkspacePrepareResult) => {
819	    if (!result || typeof result.requestId !== "number") return;
820	    prepareRequests.answer(result.requestId, result.ok === true);
821	  });
822	}
823	
824	/** Re-list the switcher in every window (the lock changed: a take started or ended). */
825	export function notifyWorkspaceBusyChanged(): void {
826	  if (registry && gate) void broadcastState();
827	}
