1	import { resolve } from "node:path";
2	import { relocateActive, type ActiveTransactionDeps } from "./switch-transaction";
3	import type { RelocateOutcome, WorkspaceRegistry } from "./registry";
4	
5	/**
6	 * "Change folder…" (relocate), after the folder picker: point a workspace at the folder where it
7	 * now lives. Pure of Electron, so every rule is unit-tested. It never moves, copies or writes
8	 * the user's files; the registry's `relocate` holds the rules about which folders qualify.
9	 */
10	export interface RelocateDeps extends ActiveTransactionDeps {
11	  registry: Pick<WorkspaceRegistry, "get" | "active" | "readOnly" | "checkRelocate" | "relocate">;
12	}
13	
14	/**
15	 * Refused before the picker opens: no point asking for a folder that could not be used. The
16	 * lock holds for every workspace, not only the active one: a take or an export is running.
17	 */
18	export function relocateRefusal(
19	  deps: Pick<RelocateDeps, "registry" | "busy">,
20	  id: string,
21	): Extract<RelocateOutcome, { ok: false }> | null {
22	  if (deps.registry.readOnly) return { ok: false, reason: "read-only" };
23	  if (!deps.registry.get(id)) return { ok: false, reason: "unknown" };
24	  const busy = deps.busy();
25	  return busy ? { ok: false, reason: busy } : null;
26	}
27	
28	export async function relocateWorkspace(
29	  deps: RelocateDeps,
30	  id: string,
31	  chosen: string,
32	): Promise<RelocateOutcome> {
33	  const refused = relocateRefusal(deps, id);
34	  if (refused) return refused;
35	  // Validated before any window is asked to prepare: a folder that will be refused costs the
36	  // user no "unsaved changes" question.
37	  const checked = await deps.registry.checkRelocate(id, chosen);
38	  if (!checked.ok) return checked;
39	  // The folder it already points at (the picker opens right there): nothing to change, so no
40	  // window is asked to save, no capture is dropped and no route remounts. The caller's probe
41	  // still runs, which rewrites an identity file deleted by hand.
42	  const current = deps.registry.get(id);
43	  if (current && resolve(current.path) === resolve(chosen)) {
44	    return { ok: true, entry: current, unchanged: true };
45	  }
46	  if (id !== deps.registry.active().id) return deps.registry.relocate(id, chosen);
47	  // The active workspace's items are open in the windows: same transaction as a switch.
48	  return relocateActive(deps, id, () => deps.registry.relocate(id, chosen));
49	}
