1	import { execFile } from "node:child_process";
2	import { realpath } from "node:fs/promises";
3	import { homedir } from "node:os";
4	import { join } from "node:path";
5	import type { SyncProvider } from "@shared/types/workspaces";
6	
7	/**
8	 * Which cloud provider syncs a workspace folder, if any (spec, Synced folders; decision 15).
9	 * Kaipu does not sync to these providers: a folder inside one is detected and labelled, and the
10	 * workspace then keeps its scratch files outside the folder, never hard-links its media and
11	 * never reads an evicted file.
12	 *
13	 * Detection is by path after `realpath`, plus Google Drive's own xattr on `identity.json` for a
14	 * folder the path rule misses. It never lists a directory and never reads a file's data: in
15	 * the spike, listing the provider root hung for minutes while `stat` and xattr reads answered.
16	 */
17	
18	/** Google Drive for desktop tags every file it syncs with this xattr (spike, DriveFS 133). */
19	export const GOOGLE_DRIVE_ITEM_XATTR = "com.google.drivefs.item-id#S";
20	
21	/** How long a detection step may take before it counts as "no answer". */
22	export const SYNC_DETECT_TIMEOUT_MS = 2_000;
23	
24	/** The provider a path lives under, from the path alone. */
25	export function syncProviderOfPath(path: string, home: string = homedir()): SyncProvider | null {
26	  const cloudStorage = join(home, "Library", "CloudStorage");
27	  const iCloud = join(home, "Library", "Mobile Documents", "com~apple~CloudDocs");
28	  const under = (root: string): boolean => path === root || path.startsWith(`${root}/`);
29	  if (under(iCloud)) return "icloud";
30	  if (!path.startsWith(`${cloudStorage}/`)) return null;
31	  const provider = path.slice(cloudStorage.length + 1).split("/")[0] ?? "";
32	  if (provider.startsWith("GoogleDrive-")) return "google-drive";
33	  if (provider.startsWith("OneDrive")) return "onedrive";
34	  return provider.length > 0 ? "cloud-provider" : null;
35	}
36	
37	export interface SyncDetectDeps {
38	  home: string;
39	  realpath(path: string): Promise<string>;
40	  /** Whether `file` carries the xattr `name`. Reading an xattr never downloads the file. */
41	  hasXattr(file: string, name: string): Promise<boolean>;
42	  timeoutMs: number;
43	}
44	
45	/** `value`, or `fallback` when it does not settle in `ms` (or rejects). */
46	export async function withTimeout<T>(value: Promise<T>, ms: number, fallback: T): Promise<T> {
47	  let timer: NodeJS.Timeout | undefined;
48	  const timeout = new Promise<T>((resolve) => {
49	    timer = setTimeout(() => resolve(fallback), ms);
50	  });
51	  try {
52	    return await Promise.race([value.catch(() => fallback), timeout]);
53	  } finally {
54	    clearTimeout(timer);
55	  }
