    else setFolderError(relocateRefusalMessage(result, editing.name, t));
  } catch {
    // Rejected after main may already have applied the new folder: the result is unknown.
    setFolderError(t("relocateUncertain"));
  } finally {
    setRelocating(false);
  }
};

